1	/**
2	 * Common Execution Spine & Invocation Pipeline
3	 * Nexus Issue #12 — WP-01 (INC-02, EXEC-001..013, FAIL-001..004, F-09)
4	 */
5	
6	import { randomUUID } from "node:crypto";
7	import { ExecutionResult } from "../types.js";
8	import {
9	  CanonicalCapability,
10	  CapabilityRegistry,
11	  defaultRegistry,
12	  CapabilityHandler,
13	  changesWorkspace,
14	} from "./capabilities.js";
15	import type { SkillAttribution } from "./skill_activation.js";
16	import { sandboxDenialEvent, sandboxEngineLabel, type SandboxDenialEvent } from "../sandbox_events.js";
17	
18	export interface InvocationRequest {
19	  /** Unique invocation identity (assigned if omitted) (EXEC-002) */
20	  invocationId?: string;
21	  /** Owning task identity (EXEC-002) */
22	  taskId?: string;
23	  /** Actor identity requesting invocation (ACT-001..004, EXEC-008) */
24	  actor?: "agent" | "subagent" | "operator" | "extension" | string;
25	  /** Execution domain in effect (EXEC-013) */
26	  executionDomain?: "agent_orchestration" | "operator_direct_shell" | "subagent" | "extension" | string;
27	  /** Model-visible tool name */
28	  toolName: string;
29	  /** Invocation arguments */
30	  args: Record<string, any>;
31	  /** Step index in active turn */
32	  stepIndex?: number;
33	  /** Active skill attribution (WP-GS-01); omitted when no activation or disabled */
34	  skillAttribution?: SkillAttribution;
35	}
36	
37	export interface InvocationContext {
38	  /** Effective verified workspace or worktree root path (EXEC-003) */
39	  workspaceRoot: string;
40	  /** Dry-run simulation mode flag */
41	  dryRun?: boolean;
42	  /** Read-only mode flag */
43	  readOnly?: boolean;
44	  /** Custom metadata */
45	  metadata?: Record<string, any>;
46	  /** RustCoreBridge instance if available */
47	  bridge?: any;
48	  /** Fallback default execution handler */
49	  defaultHandler?: (
50	    toolName: string,
51	    args: Record<string, any>,
52	    context: InvocationContext
53	  ) => Promise<ExecutionResult>;
54	  [key: string]: any;
55	}
56	
57	export interface AdmissionDecision {
58	  admitted: boolean;
59	  reason?: string;
60	  effectiveScope?: string;
61	}
62	
63	export interface ResourceConfinementDecision {
64	  confined: boolean;
65	  reason?: string;
66	  normalizedPath?: string;
67	}
68	
69	export interface EgressDecision {
70	  allowed: boolean;
71	  quarantined?: boolean;
72	  sanitizedArgs?: Record<string, any>;
73	  reason?: string;
74	}
75	
76	export interface ProcessLifecycleEvent {
77	  stage: "start" | "exit" | "cancel" | "timeout";
78	  invocationId: string;
79	  toolName: string;
80	  command?: string;
81	  pid?: number;
82	  exitCode?: number;
83	  error?: string;
84	}
85	
86	export interface CandidateMutationEvent {
87	  invocationId: string;
88	  toolName: string;
89	  mutatedPaths: string[];
90	  durationMs: number;
91	}
92	
93	export interface ContextAdmissionDecision {
94	  admitted: boolean;
95	  reason?: string;
96	  tokenCount?: number;
97	}
98	
99	export interface ExecutionReceipt {
100	  /** Immutable invocation identity (EXEC-002) */
101	  invocationId: string;
102	  /** Owning task identity (EXEC-002) */
103	  taskId: string;
104	  /** Actor identity (EXEC-008, EVID-003) */
105	  actor: string;
106	  /** Execution domain (EXEC-013, EVID-003) */
107	  executionDomain: string;
108	  /** Canonical capability identity (CAP-001) */
109	  capabilityId: string;
110	  /** Model-visible tool name */
111	  toolName: string;
112	  /** Concrete affected or queried resource paths/targets (CAP-004) */
113	  targetResources: string[];
114	  /** Outcome status */
115	  success: boolean;
116	  /** Execution output string */
117	  output: string;
118	  /** Error message if failed or denied */
119	  error?: string;
120	  /** VR-3: typed sandbox refusal behind this outcome, when one happened. Evidence only; never an approval. */
121	  sandboxEvents?: SandboxDenialEvent[];
122	  /** The call may have taken effect, but its executor outcome could not be established. */
123	  outcomeUnknown?: boolean;
124	  /** Execution duration in milliseconds */
125	  durationMs: number;
126	  /** Whether candidate state was mutated by operation (CAND-001) */
127	  candidateMutated: boolean;
128	  /** High-level execution status */
129	  status: "COMPLETED" | "DENIED" | "FAILED" | "UNKNOWN" | "BLOCKED";
130	  /** Typed denial reason if status is DENIED */
131	  denialReason?: string;
132	  /** ISO 8601 timestamp (EVID-003) */
133	  timestamp: string;
134	  /** Whether operation was simulated rather than actual host effect (EXEC-010) */
135	  simulated: boolean;
136	  /** Active skill activation id when governed skill attribution is enabled (WP-GS-01) */
137	  skillActivationId?: string;
138	  /** Skill name bound to this invocation when attributed */
139	  skillName?: string;
140	  /** SHA-256 of the skill body that was activated (WP-GS-02) */
141	  skillContentDigest?: string;
142	}
143	
144	function withSkillAttribution(receipt: ExecutionReceipt, request: InvocationRequest): ExecutionReceipt {
145	  const a = request.skillAttribution;
146	  if (!a?.skillActivationId) return receipt;
147	  return {
148	    ...receipt,
149	    ...(a.skillActivationId ? { skillActivationId: a.skillActivationId } : {}),
150	    ...(a.skillName ? { skillName: a.skillName } : {}),
151	    ...(a.skillContentDigest ? { skillContentDigest: a.skillContentDigest } : {}),
152	  };
153	}
154	
155	/**
156	 * The 7 Upfront Hook Interfaces for Downstream Increments (F-09)
157	 */
158	export type AuthorityAdmissionHook = (
159	  request: InvocationRequest,
160	  context: InvocationContext
161	) => Promise<AdmissionDecision>;
162	
163	export type ResourceConfinementHook = (
164	  request: InvocationRequest,
165	  context: InvocationContext
166	) => Promise<ResourceConfinementDecision>;
167	
168	export type EgressQuarantineHook = (
169	  request: InvocationRequest,
170	  context: InvocationContext
171	) => Promise<EgressDecision>;
172	
173	export type ProcessLifecycleHook = (
174	  event: ProcessLifecycleEvent,
175	  context: InvocationContext
176	) => Promise<void>;
177	
178	export type CandidateMutationHook = (
179	  event: CandidateMutationEvent,
180	  context: InvocationContext
181	) => Promise<void>;
182	
183	export type ContextAdmissionHook = (
184	  request: InvocationRequest,
185	  context: InvocationContext
186	) => Promise<ContextAdmissionDecision>;
187	
188	export type EvidenceEmissionHook = (
189	  receipt: ExecutionReceipt
190	) => Promise<void>;
191	
192	export interface SpineHooks {
193	  authorityAdmission?: AuthorityAdmissionHook;
194	  resourceConfinement?: ResourceConfinementHook;
195	  egressQuarantine?: EgressQuarantineHook;
196	  processLifecycle?: ProcessLifecycleHook;
197	  candidateMutation?: CandidateMutationHook;
198	  contextAdmission?: ContextAdmissionHook;
199	  evidenceEmission?: EvidenceEmissionHook;
200	}
201	
202	export interface SpineOptions {
203	  registry?: CapabilityRegistry;
204	  hooks?: SpineHooks;
205	}
206	
207	export const DEFAULT_SPINE_HOOKS: Required<SpineHooks> = {
208	  authorityAdmission: async () => ({ admitted: true }),
209	  resourceConfinement: async () => ({ confined: true }),
210	  egressQuarantine: async (req) => ({ allowed: true, sanitizedArgs: req.args }),
211	  processLifecycle: async () => {},
212	  candidateMutation: async () => {},
213	  contextAdmission: async () => ({ admitted: true }),
214	  evidenceEmission: async () => {},
215	};
216	
217	export function extractTargetResources(
218	  _toolName: string,
219	  args: Record<string, any>
220	): string[] {
221	  const resources: string[] = [];
222	  if (!args || typeof args !== "object") return resources;
223	
224	  if (typeof args.path === "string" && args.path) {
225	    resources.push(args.path);
226	  }
227	  if (Array.isArray(args.paths)) {
228	    for (const p of args.paths) {
229	      if (typeof p === "string" && p) resources.push(p);
230	    }
231	  }
232	  if (typeof args.target_file === "string" && args.target_file) {
233	    resources.push(args.target_file);
234	  }
235	  if (typeof args.file_path === "string" && args.file_path) {
236	    resources.push(args.file_path);
237	  }
238	  if (typeof args.url === "string" && args.url) {
239	    resources.push(args.url);
240	  }
241	  if (typeof args.output_path === "string" && args.output_path) {
242	    resources.push(args.output_path);
243	  }
244	  if (typeof args.command === "string" && args.command) {
245	    resources.push(args.command);
246	  }
247	  return resources;
248	}
249	
250	function validateToolArguments(
251	  capability: CanonicalCapability,
252	  args: Record<string, any>
253	): { valid: boolean; error?: string } {
254	  if (!args || typeof args !== "object" || Array.isArray(args)) {
255	    return { valid: false, error: "Tool arguments must be a JSON object." };
256	  }
257	  const required = capability.toolDefinition.function.parameters.required;
258	  if (Array.isArray(required)) {
259	    for (const reqKey of required) {
260	      if (args[reqKey] === undefined || args[reqKey] === null) {
261	        return {
262	          valid: false,
263	          error: `Missing required parameter '${reqKey}' for tool '${capability.modelToolName}'.`,
264	        };
265	      }
266	    }
267	  }
268	  return { valid: true };
269	}
270	
271	/** Capabilities whose dry-run behavior is implemented by the workspace bridge. */
272	const BRIDGE_SIMULATED_CATEGORIES = new Set(["fs", "proc", "orchestration"]);
273	
274	/** Mutating capabilities outside the bridge must be simulated by the spine itself. */
275	export function dryRunMustSimulate(capability: Pick<CanonicalCapability, "mutating" | "category">): boolean {
276	  return capability.mutating && !BRIDGE_SIMULATED_CATEGORIES.has(capability.category);
277	}
278	
279	export class ExecutionSpine {
280	  private readonly registry: CapabilityRegistry;
281	  private readonly hooks: Required<SpineHooks>;
282	  private readonly handlers = new Map<string, CapabilityHandler>();
283	
284	  constructor(options: SpineOptions = {}) {
285	    this.registry = options.registry || defaultRegistry;
286	    this.hooks = {
287	      authorityAdmission:
288	        options.hooks?.authorityAdmission || DEFAULT_SPINE_HOOKS.authorityAdmission,
289	      resourceConfinement:
290	        options.hooks?.resourceConfinement || DEFAULT_SPINE_HOOKS.resourceConfinement,
291	      egressQuarantine:
292	        options.hooks?.egressQuarantine || DEFAULT_SPINE_HOOKS.egressQuarantine,
293	      processLifecycle:
294	        options.hooks?.processLifecycle || DEFAULT_SPINE_HOOKS.processLifecycle,
295	      candidateMutation:
296	        options.hooks?.candidateMutation || DEFAULT_SPINE_HOOKS.candidateMutation,
297	      contextAdmission:
298	        options.hooks?.contextAdmission || DEFAULT_SPINE_HOOKS.contextAdmission,
299	      evidenceEmission:
300	        options.hooks?.evidenceEmission || DEFAULT_SPINE_HOOKS.evidenceEmission,
301	    };
302	  }
303	
304	  public getRegistry(): CapabilityRegistry {
305	    return this.registry;
306	  }
307	
308	  public getHooks(): Required<SpineHooks> {
309	    return { ...this.hooks };
310	  }
311	
312	  public setHook<K extends keyof SpineHooks>(hookName: K, hook: SpineHooks[K]): void {
313	    if (hook) {
314	      this.hooks[hookName] = hook as any;
315	    }
316	  }
317	
318	  public registerHandler(toolName: string, handler: CapabilityHandler): void {
319	    this.handlers.set(toolName, handler);
320	  }
321	
322	  public getHandler(toolName: string): CapabilityHandler | undefined {
323	    return this.handlers.get(toolName);
324	  }
325	
326	  /**
327	   * Execute an invocation request through the unified 6-stage execution spine.
328	   * Every execution path dispatches through this pipeline, emitting an execution receipt.
329	   */
330	  public async execute(
331	    request: InvocationRequest,
332	    context: InvocationContext
333	  ): Promise<ExecutionReceipt> {
334	    const invocationId = request.invocationId || randomUUID();
335	    const taskId = request.taskId || "task-default";
336	    const actor = request.actor || "agent";
337	    const executionDomain = request.executionDomain || "agent_orchestration";
338	    const toolName = request.toolName;
339	    const targetResources = extractTargetResources(toolName, request.args || {});
340	    const finish = async (receipt: ExecutionReceipt): Promise<ExecutionReceipt> => {
341	      const attributed = withSkillAttribution(receipt, request);
342	      try {
343	        await this.hooks.evidenceEmission(attributed);
344	      } catch {
345	        // Degraded-mode per FAIL-003
346	      }
347	      return attributed;
348	    };
349	
350	    // Stage 1: Request Ingestion & Normalization
351	    const capability = this.registry.getByToolName(toolName);
352	    if (!capability) {
353	      return finish({
354	        invocationId,
355	        taskId,
356	        actor,
357	        executionDomain,
358	        capabilityId: "unregistered",
359	        toolName,
360	        targetResources,
361	        success: false,
362	        output: "",
363	        error: `FAIL-001: Tool '${toolName}' is not registered in CapabilityRegistry.`,
364	        durationMs: 0,
365	        candidateMutated: false,
366	        status: "FAILED",
367	        timestamp: new Date().toISOString(),
368	        simulated: Boolean(context.dryRun),
369	      });
370	    }
371	
372	    const argValidation = validateToolArguments(capability, request.args || {});
373	    if (!argValidation.valid) {
374	      const receipt: ExecutionReceipt = {
375	        invocationId,
376	        taskId,
377	        actor,
378	        executionDomain,
379	        capabilityId: capability.id,
380	        toolName,
381	        targetResources,
382	        success: false,
383	        output: "",
384	        error: `FAIL-002: Malformed arguments: ${argValidation.error}`,
385	        durationMs: 0,
386	        candidateMutated: false,
387	        status: "FAILED",
388	        timestamp: new Date().toISOString(),
389	        simulated: Boolean(context.dryRun),
390	      };
391	      return finish(receipt);
392	    }
393	
394	    // Stage 2: Context & Admission Gate
395	    try {
396	      const contextDecision = await this.hooks.contextAdmission(request, context);
397	      if (!contextDecision.admitted) {
398	        const receipt: ExecutionReceipt = {
399	          invocationId,
400	          taskId,
401	          actor,
402	          executionDomain,
403	          capabilityId: capability.id,
404	          toolName,
405	          targetResources,
406	          success: false,
407	          output: "",
408	          error: contextDecision.reason || "Context admission gate denied invocation.",
409	          durationMs: 0,
410	          candidateMutated: false,
411	          status: "DENIED",
412	          timestamp: new Date().toISOString(),
413	          simulated: Boolean(context.dryRun),
414	        };
415	        return finish(receipt);
416	      }
417	    } catch (err: any) {
418	      const receipt: ExecutionReceipt = {
419	        invocationId,
420	        taskId,
421	        actor,
422	        executionDomain,
423	        capabilityId: capability.id,
424	        toolName,
425	        targetResources,
426	        success: false,
427	        output: "",
428	        error: `FAIL-001: Context admission exception: ${err.message}`,
429	        durationMs: 0,
430	        candidateMutated: false,
431	        status: "FAILED",
432	        timestamp: new Date().toISOString(),
433	        simulated: Boolean(context.dryRun),
434	      };
435	      return finish(receipt);
436	    }
437	
438	    // Stage 3: Authority & Resource Gate
439	    try {
440	      const authorityDecision = await this.hooks.authorityAdmission(request, context);
441	      if (!authorityDecision.admitted) {
442	        const receipt: ExecutionReceipt = {
443	          invocationId,
444	          taskId,
445	          actor,
446	          executionDomain,
447	          capabilityId: capability.id,
448	          toolName,
449	          targetResources,
450	          success: false,
451	          output: "",
452	          error: authorityDecision.reason || "Authority admission gate denied invocation.",
453	          durationMs: 0,
454	          candidateMutated: false,
455	          status: "DENIED",
456	          timestamp: new Date().toISOString(),
457	          simulated: Boolean(context.dryRun),
458	        };
459	        return finish(receipt);
460	      }
461	
462	      const confinementDecision = await this.hooks.resourceConfinement(request, context);
463	      if (!confinementDecision.confined) {
464	        const receipt: ExecutionReceipt = {
465	          invocationId,
466	          taskId,
467	          actor,
468	          executionDomain,
469	          capabilityId: capability.id,
470	          toolName,
471	          targetResources,
472	          success: false,
473	          output: "",
474	          error: confinementDecision.reason || "Resource confinement gate blocked invocation.",
475	          durationMs: 0,
476	          candidateMutated: false,
477	          status: "BLOCKED",
478	          timestamp: new Date().toISOString(),
479	          simulated: Boolean(context.dryRun),
480	        };
481	        return finish(receipt);
482	      }
483	    } catch (err: any) {
484	      const receipt: ExecutionReceipt = {
485	        invocationId,
486	        taskId,
487	        actor,
488	        executionDomain,
489	        capabilityId: capability.id,
490	        toolName,
491	        targetResources,
492	        success: false,
493	        output: "",
494	        error: `FAIL-001: Authority/Resource gate exception: ${err.message}`,
495	        durationMs: 0,
496	        candidateMutated: false,
497	        status: "FAILED",
498	        timestamp: new Date().toISOString(),
499	        simulated: Boolean(context.dryRun),
500	      };
501	      return finish(receipt);
502	    }
503	
504	    // Stage 4: Pre-Execution Hooks
505	    let effectiveArgs = request.args;
506	    try {
507	      const egressDecision = await this.hooks.egressQuarantine(request, context);
508	      if (!egressDecision.allowed) {
509	        const receipt: ExecutionReceipt = {
510	          invocationId,
511	          taskId,
512	          actor,
513	          executionDomain,
514	          capabilityId: capability.id,
515	          toolName,
516	          targetResources,
517	          success: false,
518	          output: "",
519	          error: egressDecision.reason || "Egress quarantine gate blocked invocation.",
520	          durationMs: 0,
521	          candidateMutated: false,
522	          status: "DENIED",
523	          timestamp: new Date().toISOString(),
524	          simulated: Boolean(context.dryRun),
525	        };
526	        return finish(receipt);
527	      }
528	      if (egressDecision.sanitizedArgs) {
529	        effectiveArgs = egressDecision.sanitizedArgs;
530	      }
531	
532	      await this.hooks.processLifecycle(
533	        {
534	          stage: "start",
535	          invocationId,
536	          toolName,
537	          command: effectiveArgs.command,
538	        },
539	        context
540	      );
541	    } catch (err: any) {
542	      const receipt: ExecutionReceipt = {
543	        invocationId,
544	        taskId,
545	        actor,
546	        executionDomain,
547	        capabilityId: capability.id,
548	        toolName,
549	        targetResources,
550	        success: false,
551	        output: "",
552	        error: `FAIL-001: Pre-execution hook exception: ${err.message}`,
553	        durationMs: 0,
554	        candidateMutated: false,
555	        status: "FAILED",
556	        timestamp: new Date().toISOString(),
557	        simulated: Boolean(context.dryRun),
558	      };
559	      return finish(receipt);
560	    }
561	
562	    // Stage 5: Capability Dispatch
563	    const t0 = Date.now();
564	    let result: ExecutionResult;
565	    try {
566	      const handler =
567	        this.handlers.get(toolName) ||
568	        this.registry.getHandler(toolName) ||
569	        capability.handler;
570	
571	      if (context.dryRun && dryRunMustSimulate(capability)) {
572	        // These handlers may write persistent state or cause external effects. The workspace bridge cannot
573	        // simulate them, so do not invoke them while the receipt reports a dry run.
574	        result = {
575	          success: true,
576	          output: JSON.stringify({
577	            dry_run: true,
578	            action: toolName,
579	            message: `[DRY-RUN SIMULATION] Would run ${toolName}. Nothing was executed.`,
580	          }),
581	        };
582	      } else if (handler) {
583	        result = await handler(effectiveArgs, context);
584	      } else if (context.defaultHandler) {
585	        result = await context.defaultHandler(toolName, effectiveArgs, context);
586	      } else if (context.bridge && typeof context.bridge.executeTool === "function") {
587	        result = await context.bridge.executeTool(toolName, effectiveArgs, context.metadata?.verificationAuthority);
588	      } else {
589	        result = {
590	          success: false,
591	          output: "",
592	          error: `No execution handler registered for capability '${capability.id}' (tool '${toolName}').`,
593	        };
594	      }
595	    } catch (err: any) {
596	      const mayHaveTakenEffect = Boolean(capability.mutating && !context.dryRun);
597	      result = {
598	        success: false,
599	        output: "",
600	        error: mayHaveTakenEffect
601	          ? `OUTCOME UNKNOWN: Invocation exception in '${toolName}': ${err?.message || String(err)}`
602	          : `FAIL-001: Invocation exception in '${toolName}': ${err?.message || String(err)}`,
603	        // The handler was admitted and invoked. If a mutating capability throws, it may have failed after
604	        // performing its effect; do not present that as a confirmed no-effect failure.
605	        outcomeUnknown: mayHaveTakenEffect,
606	      };
607	    }
608	    const durationMs = Date.now() - t0;
609	
610	    try {
611	      await this.hooks.processLifecycle(
612	        {
613	          stage: "exit",
614	          invocationId,
615	          toolName,
616	          exitCode: result.success ? 0 : 1,
617	          error: result.error,
618	        },
619	        context
620	      );
621	    } catch {
622	      // Degraded-mode per FAIL-003: lifecycle notification error does not overwrite tool outcome
623	    }
624	
625	    // Stage 6: Post-Execution Evidence & Receipt Generation
626	    const outcomeUnknown = !result.success && !result.denialReason
627	      && Boolean(result.outcomeUnknown || result.timedOut || result.cancelled);
628	    const candidateMutated = Boolean(
629	      (result.success || outcomeUnknown) && changesWorkspace(capability) && !context.dryRun
630	    );
631	    const reportedError = outcomeUnknown && !/outcome unknown/i.test(result.error ?? "")
632	      ? `OUTCOME UNKNOWN: ${result.error ?? "no answer from the executor"}. The effect may have happened; check it before retrying, do not assume it failed.`
633	      : result.error;
634	
635	    if (candidateMutated) {
636	      try {
637	        await this.hooks.candidateMutation(
638	          {
639	            invocationId,
640	            toolName,
641	            mutatedPaths: targetResources,
642	            durationMs,
643	          },
644	          context
645	        );
646	      } catch {
647	        // Degraded-mode per FAIL-003
648	      }
649	    }
650	
651	    const sandboxDenial = result.sandboxDenial
652	      ? sandboxDenialEvent({
653	          kind: result.sandboxDenial.kind,
654	          engine: sandboxEngineLabel((context.metadata as any)?.sandbox ?? (context as any)?.config?.sandbox),
655	          operation: toolName,
656	          category: result.sandboxDenial.category,
657	          reason: result.sandboxDenial.reason,
658	        })
659	      : undefined;
660	    const receipt: ExecutionReceipt = {
661	      invocationId,
662	      taskId,
663	      actor,
664	      executionDomain,
665	      capabilityId: capability.id,
666	      toolName,
667	      targetResources,
668	      success: result.success,
669	      output: result.output || "",
670	      error: reportedError,
671	      ...(sandboxDenial ? { sandboxEvents: [sandboxDenial] } : {}),
672	      ...(outcomeUnknown ? { outcomeUnknown: true } : {}),
673	      durationMs,
674	      candidateMutated,
