    const detached = await runHookProcess({ command: `sleep 300 >/dev/null 2>&1 & echo $! > "${pidFile}"; echo ok`, cwd: dir, env: env(dir), stdin: "{}", timeoutMs: 60_000, drainMs: 500 });
