cd /home/mike/nexus-wt/hk1 && cat >> docs/protocol/README.md <<'EOF'

## The command-hook documents

`hooks-v1.schema.json` is the JSON Schema of the command-hook contract (`HooksDocument` in `cli/src/core/hooks.ts`, plan unit HK-1). `$defs.HooksFile` is a hooks file (`~/.config/nexus/hooks.json`, `<workspace>/.nexus/hooks.json`), `$defs.HookInput` the one JSON object a hook reads on standard input, `$defs.HookOutput` what it may print on standard output, and `$defs.ExtensionTrustStore` the approval store `~/.config/nexus/extension_trust.json`. It is generated by the same `SchemaBuilder` through `cli/scripts/result_schema.mjs`.

```bash
cd cli
node scripts/gen_hooks_schema.mjs           # rewrite docs/protocol/hooks-v1.schema.json
node scripts/gen_hooks_schema.mjs --check   # exit 1 when the schema or its ledger is stale
```

Its ledger is `HOOKS_VERSIONS.json`, entries `{ "schema_version", "schemaSha256", "note" }`, newest last, under the same rule as the run-result ledger with `HOOKS_SCHEMA_VERSION`. A hooks file carries the version as `version`, and the reader refuses any other value, so a removed or renamed key, or a changed meaning, bumps it; an added optional member of the hook input keeps it. `cli/test/hooks_schema.test.ts` runs the comparison.

The schema describes shape only and is looser than the reader (`parseHooksFile`): it does not reject an unknown or duplicate key, a pattern in `tools`, a repeated hook name or a `timeout_secs` out of range, all of which the reader refuses.
EOF
cat > docs/protocol/HOOKS_VERSIONS.json <<EOF
[
  {
    "schema_version": 1,
    "schemaSha256": "$(sha256sum docs/protocol/hooks-v1.schema.json | cut -d' ' -f1)",
    "note": "First published schema of the command-hook contract (HK-1), generated from HooksDocument in cli/src/core/hooks.ts on release/v1.3.0: the hooks file (events pre-tool and post-tool), a hook's standard input and standard output, and the approval store extension_trust.json (kind project-hooks). Nothing was published before it."
  }
]
EOF
cd cli && cat > test/hooks_schema.test.ts <<'EOF'
/**
 * HK-1: the hook contract as published. The checked-in JSON Schema (docs/protocol/hooks-v1.schema.json) is what the
 * types generate, its ledger records the version decision, and documents the reader accepts fit the schema.
 */
import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { sha256 } from "../scripts/gen_protocol_schema.mjs";
import { generateHooksSchema, HOOKS_LEDGER_FILE, hooksLedgerProblem, hooksSchemaFile } from "../scripts/gen_hooks_schema.mjs";
import { EXTENSION_TRUST_VERSION } from "../src/core/content_trust.js";
import { HOOK_EVENTS, HOOKS_SCHEMA_VERSION, parseHooksFile } from "../src/core/hooks.js";
import { validate } from "./helpers/json_schema.js";

const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SCHEMA_TEXT = fs.readFileSync(hooksSchemaFile(HOOKS_SCHEMA_VERSION), "utf8");
const schema = JSON.parse(SCHEMA_TEXT);
const fits = (value: unknown, def: string) => validate(value, schema.$defs[def], schema);

test("the checked-in hooks schema equals a fresh generation from src/core/hooks.ts", () => {
  const generated = generateHooksSchema();
  assert.equal(generated.version, HOOKS_SCHEMA_VERSION);
  assert.equal(generated.text, SCHEMA_TEXT, "docs/protocol/hooks schema is out of date: run `node cli/scripts/gen_hooks_schema.mjs`, then record the version decision in HOOKS_VERSIONS.json");
