    env: { ...process.env, NEXUS_TEST_PARSING_ONLY: "1" },
  });

  const combined = (res.stdout || "") + (res.stderr || "");
  const hasUnknownCommand = /unknown command/i.test(combined);
  const hasUnknownOption = /unknown option/i.test(combined);

